<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class ProfileController extends Controller { private function shape($u){return ['id'=>(int)$u->id,'full_name'=>$u->full_name,'username'=>$u->username,'email'=>$u->email,'role'=>$u->role,'avatar_path'=>$u->avatar_path];} public function update(Request $r){$u=$r->user();$name=trim(strip_tags((string)$r->input('full_name')));$email=trim(strip_tags((string)$r->input('email')));if(!$name)return response()->json(['error'=>'Full name is required'],422);if($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))return response()->json(['error'=>'Invalid email address'],422);if($email&&$u->newQuery()->where('email',$email)->whereKeyNot($u->id)->exists())return response()->json(['error'=>'Email address is already in use'],422);$u->update(['full_name'=>$name,'email'=>$email?:null]);return response()->json(['data'=>$this->shape($u)]);} public function updatePassword(Request $r){$u=$r->user();$new=(string)$r->input('new_password');if(strlen($new)<8)return response()->json(['error'=>'New password must be at least 8 characters'],422);if(!Hash::check((string)$r->input('current_password'),$u->password_hash))return response()->json(['error'=>'Current password is incorrect'],422);$u->update(['password_hash'=>Hash::make($new)]);return response()->json(['data'=>true]);} public function uploadAvatar(Request $r){if(!$r->hasFile('avatar'))return response()->json(['error'=>'No valid image uploaded'],422);$r->validate(['avatar'=>'image|mimes:png,jpg,jpeg|max:2048']);$path=$r->file('avatar')->store('uploads','public');$r->user()->update(['avatar_path'=>$path]);return response()->json(['data'=>$this->shape($r->user())]);} public function avatar(Request $r){$p=$r->user()->avatar_path;if(!$p||!\Storage::disk('public')->exists($p))return response()->json(['error'=>'Image not found'],404);return response(\Storage::disk('public')->get($p),200,['Content-Type'=>\Storage::disk('public')->mimeType($p)]);} }
